import subprocess
import time
import json
import platform
LOGFILE_PATH = "logfile.log"
def task_func(interval, duration):
    if interval <= 0 or duration <= 0:
        raise ValueError("Interval and duration must be greater than zero")
    if platform.system() == "Windows":
        command = ["wmic", "cpu", "get", "loadpercentage"]
    else:
        command = ["mpstat", "1", "1"]
    records = []
    start_time = time.time()
    try:
        while time.time() - start_time < duration:
            record_time = time.strftime("%Y-%m-%d %H:%M:%S", time.localtime())
            try:
                output = subprocess.check_output(command, shell=True).decode()
                if platform.system() == "Windows":
                    lines = output.strip().split("\n")
                    if len(lines) >= 2:
                        cpu_usage = lines[1].strip()
                    else:
                        cpu_usage = "0"
                else:
                    lines = output.strip().split("\n")
                    if len(lines) >= 2:
                        parts = lines[-1].split()
                        cpu_usage = parts[-1] if parts else "0"
                    else:
                        cpu_usage = "0"
            except subprocess.CalledProcessError:
                cpu_usage = "0"
            records.append({"timestamp": record_time, "cpu_usage": cpu_usage})
            time.sleep(interval)
    except IOError:
        return None
    try:
        with open(LOGFILE_PATH, "w") as f:
            json.dump(records, f, indent=4)
        return LOGFILE_PATH
    except IOError:
        return None
