import subprocess
import os
import threading
def task_func(script_path: str, timeout: int = 60) -> str:
    if not os.path.exists(script_path):
        raise FileNotFoundError(f"File not found: {script_path}")

    result = []
    def target():
        try:
            proc = subprocess.run(['python', script_path], capture_output=True, text=True, timeout=timeout)
            result.append(proc.returncode)
        except subprocess.TimeoutExpired:
            result.append(None)

    thread = threading.Thread(target=target)
    thread.start()
    thread.join(timeout)

    if thread.is_alive():
        return "Terminating process due to timeout."
    else:
        if result[0] is None:
            return "Terminating process due to timeout."
        else:
            return "Script executed successfully."
```

