import subprocess
import psutil
import time
import os
def task_func(script_path: str, timeout=10) -> dict:
    if not os.path.exists(script_path):
        raise FileNotFoundError(f"Script not found: {script_path}")
    process = subprocess.Popen(['bash', script_path], stdout=subprocess.PIPE, stderr=subprocess.PIPE)
    try:
        ps_process = psutil.Process(process.pid)
    except psutil.NoSuchProcess:
        return {'CPU Usage': 0.0, 'Memory Usage': 0}
    cpu_usage = 0.0
    memory_usage = 0
    start_time = time.time()
    while True:
        try:
            if not ps_process.is_running() or ps_process.status() == psutil.STATUS_ZOMBIE:
                break
            cpu_percent = ps_process.cpu_percent(interval=0.1)
            memory_info = ps_process.memory_info()
            cpu_usage += cpu_percent
            memory_usage += memory_info.rss
            if time.time() - start_time > timeout:
                process.terminate()
                process.wait()
                break
        except (psutil.NoSuchProcess, psutil.AccessDenied):
            break
    return {'CPU Usage': cpu_usage, 'Memory Usage': memory_usage}
