import logging
def task_func(filepath):
    try:
        result = subprocess.run(['g++', filepath], capture_output=True, text=True)
        if result.returncode == 0:
            logging.info(f"Compilation successful for {filepath}")
        else:
            logging.error(f"Compilation failed for {filepath}: {result.stderr}")
            raise subprocess.CalledProcessError(result.returncode, result.args, output=result.stdout, stderr=result.stderr)
    except FileNotFoundError:
        logging.error(f"Compiler not found or file {filepath} does not exist")
        raise
